def _validate(cap_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    """Refuse a partial, out-of-vocabulary or unknown-field record with a 4xx."""
    if not isinstance(payload, dict):
        raise HTTPException(status_code=422, detail="payload must be an object")
    from app import security

    try:
        security.guard_payload(payload)
