def _read_one(cap_id: str, record_id: int, request: Request) -> Dict[str, Any]:
    """One record, or 404. Another tenant's record is invisible, not forbidden."""
    tenant = require_read_scope(request)
    # The id column is a signed 64-bit integer. An id outside that range
    # cannot exist, and handing it to the driver is an OverflowError (500) --
    # so it answers 404, the same answer a well-formed absent id gets, which
    # leaks nothing about what is stored.
    if not (0 <= record_id <= INT64_MAX):
        raise HTTPException(status_code=404, detail="not found")
    record = store.get(_entity_of(cap_id), record_id, tenant_id=tenant.tenant_id)
