        return _list(cap_id, request)

    def read_record(record_id: int, request: Request) -> Dict[str, Any]:
        return _read_one(cap_id, record_id, request)

    create.__name__ = "create_" + cap_id
    list_records.__name__ = "list_" + cap_id
    read_record.__name__ = "read_" + cap_id
    router.add_api_route("/" + cap_id, create, methods=["POST"], name="create_" + cap_id)
    router.add_api_route("/" + cap_id, list_records, methods=["GET"], name="list_" + cap_id)
    router.add_api_route("/" + cap_id + "/{record_id}", read_record, methods=["GET"],
                         name="read_" + cap_id)


