"""Deterministic winery formulas: fermentation progress, harvest readiness, barrel age.

Written by the factory WRITER role (codewhale exec)

These are the deterministic computations behind the tank, barrel and harvest
views: sugar consumed and per-cent completion against the winery's dry
threshold, the harvest readiness band from a sampled Brix and the block target,
and a barrel's age and topping interval. Every function returns a labelled
result (app/authority.py layer 3, formulas) so an operator can see that a figure
was computed, not quoted.

Vocabulary: dates are ISO ``YYYY-MM-DD``. Nothing here reads the clock unless a
caller passes ``today``, so a report is reproducible.
"""

from __future__ import annotations

from datetime import date, datetime
from typing import Any, Dict, Optional

from app.authority import LAYER_FORMULAS, label

DRY_BRIX = 0.5
READY_BAND = 0.5
MONITOR_BAND = 1.5
TOPPING_INTERVAL_DAYS = 45
RACKING_INTERVAL_DAYS = 120


def _f(value: Any, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _as_date(value: Any) -> Optional[date]:
    if value in (None, ""):
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value).strip()[:19]
    for fmt in ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%d/%m/%Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    return None


def _labelled(kind: str, source: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    return {**payload, "formula": kind, "authority": label(LAYER_FORMULAS, source).to_dict()}


def fermentation_progress(brix_start: Any, brix_current: Any) -> Dict[str, Any]:
    """Sugar consumed and completion against the dry threshold."""
    start = _f(brix_start)
    current = _f(brix_current)
    consumed = start - current
    completion = (consumed / start) if start > 0 else 0.0
    completion = max(0.0, min(1.0, completion))
    if current <= DRY_BRIX:
        stage = "dry"
    elif consumed <= 0.0:
        stage = "inoculation"
    elif consumed < 0.02:
        stage = "stuck"
    elif consumed < 0.1:
        stage = "slow"
    else:
        stage = "active"
    return _labelled("fermentation_progress", "fermentation completion formula", {
        "brix_start": start,
        "brix_current": current,
        "sugar_consumed_brix": round(consumed, 3),
        "completion": round(completion, 4),
        "completion_pct": round(completion * 100.0, 1),
        "dry_remaining_brix": round(max(0.0, current - DRY_BRIX), 3),
        "stage": stage,
    })


def harvest_readiness(brix_reading: Any, target_brix: Any, ph: Any = None) -> Dict[str, Any]:
    """The readiness band from a sampled Brix and the block's target."""
    brix = _f(brix_reading)
    target = _f(target_brix)
    ph_value = _f(ph)
    gap = round(target - brix, 3)
    if target <= 0:
        state = "monitor"
    elif gap <= READY_BAND:
        state = "ready"
    elif gap <= MONITOR_BAND:
        state = "monitor"
    else:
        state = "not_ready"
    if ph_value and ph_value >= 3.8:
        state = "hold"
    return _labelled("harvest_readiness", "harvest readiness by sugar reading", {
        "brix_reading": brix,
        "target_brix": target,
        "brix_gap": gap,
        "ph": ph_value,
        "readiness": state,
    })


def barrel_age(fill_date: Any, record_date: Any = None,
               today: Optional[date] = None) -> Dict[str, Any]:
    """A barrel's age in months and the topping/racking states it implies."""
    fill = _as_date(fill_date)
    reference = _as_date(record_date) or (today or date.today())
    now = today or date.today()
    age_days = (now - fill).days if fill else 0
    since_record = (now - reference).days if reference else 0

    def _state(days: int, interval: int) -> str:
        if days >= interval:
            return "overdue"
        if days >= int(interval * 0.75):
            return "due"
        return "current"

    return _labelled("barrel_age", "barrel age and topping interval", {
        "fill_date": fill.isoformat() if fill else "",
        "age_days": age_days,
        "age_months": round(age_days / 30.4375, 1) if fill else 0.0,
        "days_since_record": since_record,
        "topping_state": _state(since_record, TOPPING_INTERVAL_DAYS),
        "racking_state": _state(since_record, RACKING_INTERVAL_DAYS),
    })

    try:
        from app.placeholders import PLACEHOLDER_CONNECTORS
    except Exception:
        PLACEHOLDER_CONNECTORS = {}
    for cap in _cap_order():
        if PLACEHOLDER_CONNECTORS.get(cap):
            continue
        required, enum = _required_and_enum(cap)
        found = required if want == "required" else enum
        if found:
            return cap, found
    return "", None


