from __future__ import annotations

from typing import Any, Dict, Optional

from app import authority, formulas
from app.block_inputs import prepare_block_input
from app.domain_blocks import block_refusal, public_results, run_declared_blocks

AUTHORED_BY = "codewhale exec"

CAPABILITY_ID = "winery_operations_dashboard"
ENTITY = "winery_operations_dashboard"
SOURCE = "operations view"
INVARIANT_ID = "dashboard_bounds"
BLOCK_IDS = ["dashboard", "analytics"]
BLOCK_DEFAULT_ACTIONS = {
    "dashboard": "render",
    "analytics": "track_event",  # analytics' own declared default (params.action)
}
CAPABILITY_FIELDS = [
    "reference", "status", "view", "cellar", "as_of", "tank_count",
    "barrel_count", "harvest_blocks", "shipments_pending", "note",
]

VIEWS = ("tanks", "barrels", "harvest", "club", "all")
CELLARS = ("cellar_one", "cellar_two")


def _i(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _invariant(record: Dict[str, Any]) -> Optional[str]:
    view = str(record.get("view") or "")
    if view and view not in VIEWS:
        return "view must be one of: " + ", ".join(VIEWS)
    cellar = str(record.get("cellar") or "")
    if cellar and cellar not in CELLARS:
        return "cellar must be one of: " + ", ".join(CELLARS)
    for name in ("tank_count", "barrel_count", "harvest_blocks", "shipments_pending"):
        if _i(record.get(name)) < 0:
            return "%s cannot be negative" % name
    return None


def _decide(record: Dict[str, Any]) -> Dict[str, Any]:
    counts = {
        "tanks": _i(record.get("tank_count")),
        "barrels": _i(record.get("barrel_count")),
        "harvest": _i(record.get("harvest_blocks")),
        "club": _i(record.get("shipments_pending")),
    }
    view = str(record.get("view") or "all")
    selected = counts if view == "all" else {view: counts.get(view, 0)}
    return {
        "view": view,
        "cellar": str(record.get("cellar") or "cellar_one"),
        "as_of": str(record.get("as_of") or ""),
        "counts": counts,
        "selected": selected,
        "headline": ("%s view: %s" % (view, ", ".join("%s=%d" % kv for kv in sorted(selected.items())))),
    }


def _block_input(block_id: str, record: Dict[str, Any], decision: Dict[str, Any]) -> Dict[str, Any]:
    if block_id == "dashboard":
        return prepare_block_input(
            "dashboard",
            {"widget": "winery_operations", "title": "Winery operations",
             "layout": "grid",
             "data": {"view": decision["view"], "cellar": decision["cellar"],
                      "counts": decision["counts"], "as_of": decision["as_of"]}},
            entity=ENTITY, default_actions=BLOCK_DEFAULT_ACTIONS)
    return prepare_block_input(
        "analytics",
        {"metric": "winery_operations", "value": sum(decision["counts"].values()),
         "dimensions": {"view": decision["view"], "cellar": decision["cellar"]}},
        entity=ENTITY, default_actions=BLOCK_DEFAULT_ACTIONS)

def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    record = dict(payload or {})
    label = authority.label(authority.LAYER_FORMULAS, SOURCE)
    refusal = _invariant(record)
    if refusal:
        return {"ok": False, "capability": CAPABILITY_ID, "refused": True,
                "invariant_id": INVARIANT_ID, "error": refusal,
                "authority": label.to_dict()}
    board = _decide(record)
    results = run_declared_blocks(
        BLOCK_IDS, BLOCK_DEFAULT_ACTIONS,
        lambda block_id: _block_input(block_id, record, board))
    blocked = block_refusal(CAPABILITY_ID, results, INVARIANT_ID, label.to_dict())
    if blocked:
        return blocked
    return {"ok": True, "capability": CAPABILITY_ID, "refused": False,
            "view": board["view"], "headline": board["headline"],
            "board": {"counts": board["counts"], "cellar": board["cellar"],
                      "as_of": board["as_of"]},
            "blocks": public_results(results), "authority": label.to_dict()}

